import React, { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { increment, decrement, reset } from "../features/counterSlice";
// import { fetchData } from "../features/apiSlice";
import "./counter.css"; 

const Counter = () => {
  const count = useSelector((state) => state.counter.value);
//   const apiData = useSelector((state) => state.api.data);
//   const apiStatus = useSelector((state) => state.api.status);
//   const dispatch = useDispatch();

//   useEffect(() => {
//     if (apiStatus === "idle") {
//       dispatch(fetchData());
//     }
//   }, [apiStatus, dispatch]);

  return (
    <div className="counter-container">
      <h1 className="counter-value">Counter: {count}</h1>
      <div className="counter-buttons">
        <button onClick={() => dispatch(increment())}>Increment</button>
        <button onClick={() => dispatch(decrement())}>Decrement</button>
        <button onClick={() => dispatch(reset())}>Reset</button>
      </div>

      <div className="api-section">
        <h2 className="api-title">API Data:</h2>
        {apiStatus === "loading" && <p>Loading...</p>}
        {apiStatus === "failed" && <p>Error fetching data</p>}
        <ul className="api-list">
          {apiData.slice(0, 5).map((post) => (
            <li key={post.id}>{post.title}</li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default Counter;
